<p>Model:</p>
<pre class="lang-php prettyprint-override"><code>public function getActiveImages(): array
{
    return $this-&gt;db-&gt;get_where('penyaluran', ['status' =&gt; 1])-&gt;result();
}
</code></pre>
<p>Controller:</p>
<pre class="lang-php prettyprint-override"><code>public function home()
{
